@push('styles')
<style>
.gdm{max-width:1440px;margin:auto;color:var(--text-primary,#17243b)}.gdm h2,.gdm h3{margin:0 0 8px}.gdm .muted{color:var(--text-secondary,#64748b);font-size:13px}.gdm .panel{background:var(--card-bg,#fff);border:1px solid var(--border-color,#dce3ed);border-radius:14px;padding:22px;margin:18px 0}.gdm .hero{display:flex;align-items:center;justify-content:space-between;gap:16px}.gdm .badge-draft{background:#fff3d5;color:#825600;border-radius:20px;padding:7px 12px;font-size:12px;font-weight:600;white-space:nowrap}.gdm .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin:16px 0}.gdm label{display:block;font-size:12px;font-weight:600;margin-bottom:5px}.gdm input:not([type=checkbox]):not([type=radio]),.gdm select,.gdm textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;background:var(--card-bg,#fff);color:inherit;font:inherit;font-size:13px}.gdm .actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.gdm .cta{background:#233f88;color:white;border:0;border-radius:8px;padding:11px 16px;font-size:13px;cursor:pointer;text-decoration:none}.gdm .secondary{background:#eef2f8;color:#233f88}.gdm .scroll{overflow:auto;max-width:100%}.gdm table{width:100%;border-collapse:collapse;font-size:12px}.gdm th{background:var(--bg-secondary,#f3f6fa);text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.03em}.gdm td,.gdm th{padding:12px;border-bottom:1px solid #e2e8f0;vertical-align:top}.gdm .note{border-left:3px solid #d89a19;background:#fff9eb;color:#72541c;padding:12px 16px;border-radius:6px;font-size:13px}.gdm .success{background:#e9f8f0;color:#176044;padding:12px;border-radius:8px}.gdm .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.gdm .stats strong{display:block;font-size:26px}.gdm .stats>div{padding:18px;background:var(--card-bg,#fff);border:1px solid #dce3ed;border-radius:12px}.gdm .check{display:flex;gap:9px;align-items:center;font-size:13px;font-weight:400}.gdm details summary{cursor:pointer;font-weight:600}.gdm .err{color:#ad2828}.gdm .paginator{margin-top:16px}@media(max-width:640px){.gdm .hero{align-items:flex-start;flex-direction:column}.gdm .panel{padding:15px}.gdm .stats{grid-template-columns:1fr}.gdm .fields{grid-template-columns:1fr}.gdm table{min-width:680px}}
</style>
@endpush
